using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BusShelterUpgrade{const string D="Assets/Scenes/Oasis/BusShelterUpgrade/",Bus="Assets/Scenes/Oasis/3D/Prefeb/Bus stop.prefab";static BusShelterUpgrade(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BusShelterUpgrade.request"))return;File.Delete("BusShelterUpgrade.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BusShelterUpgrade.txt",e.ToString());Debug.LogException(e);}}static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var target=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(f=>f.name=="Bus stop - City 02 - polySurface842");var original=target.sharedMesh;if(AssetDatabase.GetAssetPath(original).StartsWith(D))throw new Exception("Shared bus shelter already updated");var matches=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh==original).ToArray();var transforms=matches.Select(f=>new{f,m=f.transform.localToWorldMatrix}).ToArray();var mat=target.GetComponent<Renderer>().sharedMaterial;string atlasPath=AssetDatabase.GetAssetPath(mat.GetTexture("_BaseMap"));var pixels=System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes(atlasPath));Directory.CreateDirectory(D);Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeSharedBusShelterUpgrade");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeSharedBusShelterUpgrade/Scene.unity",true);var paths=new[]{Bus,"Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/Citywide Bus Stops.prefab","Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab"};for(int i=0;i<paths.Length;i++)File.Copy(paths[i],"FinalEnvironmentRoadBackup/BeforeSharedBusShelterUpgrade/Prefab"+i+".prefab",true);
var near=StackHouse3DSigns.BuildBusShelter(true,original.bounds,mat);var far=StackHouse3DSigns.BuildBusShelter(false,original.bounds,mat);AssetDatabase.CreateAsset(near,D+"Bus Shelter Shared Near.asset");AssetDatabase.CreateAsset(far,D+"Bus Shelter Shared Far.asset");var prefab=PrefabUtility.LoadPrefabContents(Bus);try{var mf=prefab.GetComponent<MeshFilter>();mf.sharedMesh=near;var r=prefab.GetComponent<MeshRenderer>();r.sharedMaterial=mat;var distant=new GameObject("Mobile distant shelter");distant.transform.SetParent(prefab.transform,false);distant.AddComponent<MeshFilter>().sharedMesh=far;var fr=distant.AddComponent<MeshRenderer>();fr.sharedMaterial=mat;fr.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var lod=prefab.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.065f,new Renderer[]{r}),new LOD(.003f,new Renderer[]{fr})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,Bus);}finally{PrefabUtility.UnloadPrefabContents(prefab);}
int overrides=0;foreach(string path in paths.Skip(1)){var p=PrefabUtility.LoadPrefabContents(path);try{foreach(var f in p.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("Bus stop")&&(f.sharedMesh==original||f.sharedMesh==near))){var prop=new SerializedObject(f).FindProperty("m_Mesh");if(prop.prefabOverride)PrefabUtility.RevertPropertyOverride(prop,InteractionMode.AutomatedAction);if(f.sharedMesh!=near){f.sharedMesh=near;PrefabUtility.RecordPrefabInstancePropertyModifications(f);}overrides++;}PrefabUtility.SaveAsPrefabAsset(p,path);}finally{PrefabUtility.UnloadPrefabContents(p);}}
// Existing city copies contain mesh overrides; clear these so source-prefab edits propagate.
var current=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name.StartsWith("Bus stop")&&(f.sharedMesh==original||f.sharedMesh==near)).ToArray();foreach(var f in current){var prop=new SerializedObject(f).FindProperty("m_Mesh");if(prop.prefabOverride)PrefabUtility.RevertPropertyOverride(prop,InteractionMode.AutomatedAction);if(f.sharedMesh!=near){f.sharedMesh=near;PrefabUtility.RecordPrefabInstancePropertyModifications(f);}}foreach(var item in transforms)if(item.f&&item.f.transform.localToWorldMatrix!=item.m)throw new Exception("Bus stop placement changed: "+item.f.name);if(!pixels.SequenceEqual(System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes(atlasPath))))throw new Exception("Existing atlas source pixels changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);int linked=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Count(f=>f.sharedMesh==near);int lods=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true)).Count(l=>l.GetComponent<MeshFilter>()&&l.GetComponent<MeshFilter>().sharedMesh==near);File.WriteAllText("FinalEnvironmentRoadReview/BusShelterUpgrade.txt","SUCCESS source Bus stop.prefab updated; city copies="+linked+" LOD groups="+lods+" nested prefab mesh overrides processed="+overrides+". Existing source atlas pixels/material unchanged. Dark shelter frame, timber bench using same wood atlas island, map/route display, existing side advert/timetable atlas crops, BUS STOP header and bus marker, warm emissive strips. No new textures/materials/plants/exterior props or realtime lights. Shared mesh triangles near="+near.triangles.Length/3+" far="+far.triangles.Length/3+". Saved original shared prefab + citywide/nested road prefab + scene; placements preserved. Shader error="+ShaderUtil.ShaderHasError(mat.shader));}}
